import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    invoices = inputs["invoices"].copy()
    payments = inputs["payments"].copy()

    # Initialize tracking structures
    allocations = []

    # Create a mutable copy of invoice state: track open_amount for each invoice
    invoice_state = {}
    for _, row in invoices.iterrows():
        invoice_state[row['invoice_id']] = {
            'customer_id': row['customer_id'],
            'due_date': row['due_date'],
            'original_amount': row['amount'],
            'open_amount': row['amount'],
            'applied_amount': 0.0
        }

    # Track unapplied credit per customer
    customer_credit_dict = {}

    # Sort payments by customer_id, then paid_ts, then payment_id (for determinism)
    payments_sorted = payments.sort_values(
        by=['customer_id', 'paid_ts', 'payment_id'],
        ignore_index=True
    )

    # Process each payment
    for _, payment_row in payments_sorted.iterrows():
        payment_id = payment_row['payment_id']
        customer_id = payment_row['customer_id']
        paid_ts = payment_row['paid_ts']
        amount = payment_row['amount']

        left = amount

        # Get all invoices for this customer with open_amount > 0
        customer_invoices = [
            (inv_id, state)
            for inv_id, state in invoice_state.items()
            if state['customer_id'] == customer_id and state['open_amount'] > 0
        ]

        # Sort by due_date, then invoice_id (oldest first)
        customer_invoices.sort(
            key=lambda x: (x[1]['due_date'], x[0])
        )

        # Allocate payment to invoices
        for invoice_id, inv_state in customer_invoices:
            if left <= 0:
                break

            pay = min(left, inv_state['open_amount'])
            inv_state['open_amount'] -= pay
            inv_state['applied_amount'] += pay
            left -= pay

            allocations.append({
                'payment_id': payment_id,
                'invoice_id': invoice_id,
                'applied_amount': pay
            })

        # Remaining amount becomes unapplied credit
        if left > 0:
            if customer_id not in customer_credit_dict:
                customer_credit_dict[customer_id] = 0.0
            customer_credit_dict[customer_id] += left

    # Build invoice_status output
    invoice_status_rows = []
    for invoice_id, state in invoice_state.items():
        open_amount = state['open_amount']

        # Determine status
        if open_amount == 0:
            status = 'PAID'
        elif state['applied_amount'] == 0:
            status = 'OPEN'
        else:
            status = 'PARTIAL'

        invoice_status_rows.append({
            'invoice_id': invoice_id,
            'open_amount': open_amount,
            'status': status
        })

    invoice_status = pd.DataFrame(invoice_status_rows)

    # Build allocations output
    if allocations:
        allocations_df = pd.DataFrame(allocations)
    else:
        allocations_df = pd.DataFrame(
            columns=['payment_id', 'invoice_id', 'applied_amount']
        )
        allocations_df = allocations_df.astype({
            'payment_id': 'int64',
            'invoice_id': 'int64',
            'applied_amount': 'float64'
        })

    # Build customer_credit output
    if customer_credit_dict:
        customer_credit_rows = [
            {'customer_id': cust_id, 'unapplied_amount': amount}
            for cust_id, amount in customer_credit_dict.items()
            if amount > 0
        ]
        customer_credit = pd.DataFrame(customer_credit_rows)
    else:
        customer_credit = pd.DataFrame(
            columns=['customer_id', 'unapplied_amount']
        )
        customer_credit = customer_credit.astype({
            'customer_id': 'int64',
            'unapplied_amount': 'float64'
        })

    # Ensure correct dtypes
    invoice_status = invoice_status.astype({
        'invoice_id': 'int64',
        'open_amount': 'float64',
        'status': 'object'
    })

    if len(allocations_df) > 0:
        allocations_df = allocations_df.astype({
            'payment_id': 'int64',
            'invoice_id': 'int64',
            'applied_amount': 'float64'
        })

    if len(customer_credit) > 0:
        customer_credit = customer_credit.astype({
            'customer_id': 'int64',
            'unapplied_amount': 'float64'
        })

    return {
        'invoice_status': invoice_status,
        'allocations': allocations_df,
        'customer_credit': customer_credit
    }
